          answerEn: "OK, I admit I was wrong, you were right; he is a nice guy. (This seems to be a situation where somebody is accusing someone or trying to get them to say they were wrong. Admit is ideal in this case.",
          answerFa: "باشه، من می‌پذیرم که من اشتباه بودم و شما حق داشتید؛ او آدم خوبی است."
