          answerEn: "The company acknowledges that you have suffered some delay, but we do not accept liability. (Acknowledge is perhaps best here; it is often used in formal, legalistic situations like this because it simply says 'We understand your message, but we do not necessarily accept any blame/responsibility'; admit might suggest the company does accept legal responsibility; accept is also possible though less formal.)",
          answerFa: "شرکت می‌پذیرد که شما با تأخیر مواجه شده‌اید، اما ما مسئولیت آن را نمی‌پذیریم."
