          answerEn: "I never got a chance to tell him. Still, I'm seeing him next week. I'll tell him then. Follow-up: If it is difficult or impossible for you to get hold of tape-recordings of natural conversation, there are tapes and transcripts of everyday English conversation in R. Carter and M. McCarthy, Exploring Spoken English (Cambridge University Press, 1997), where you will find a wide range of spoken discourse markers in actual use, with commentaries.",
          answerFa: "هرگز فرصتی پیدا نکردم که بهش بگم. با این حال، هفته بعدشو می‌بینم. اون موقع بهش می‌گم. پیگیری: اگر برای دسترسی به ضبط‌های گفتگوی طبیعی برات سخته یا غیرممکنه، نوارها و نسخه‌های نوشتاری گفتگوی روزمره انگلیسی در آر. کارتر و ام. مکارتی، کاوش در زبان گفتاری انگلیسی (انتشارات دانشگاه کمبریج، ۱۹۹۷) وجود داره، که طیف وسیعی از نشانه‌های گفتگوی گفتاری به کار رفته در عمل رو با توضیحات پیدا می‌کنی."
