          answerEn: "Sample letter: Dear Editor, With reference to the article in your newspaper about the closure of Mainton Hospital, I would like to express my strong opposition to the proposal, for the following reasons. Firstly, the nearest other hospital is 50 kilometres away. Secondly, 200 people work at the hospital and they will lose their jobs and the whole region will suffer; that is to say the hospital makes an important contribution to the local economy. Finally, it is the only hospital in the region with a special cancer unit. But leaving aside the economic and medical questions, the hospital is obviously being closed for political reasons, and this is quite wrong. To sum up, the closure of our hospital would be a disaster both for the people and for the economy of this region. Yours sincerely, Anne Gree (Ms)",
          answerFa: "نمونه نامه: احتراماً، با اشاره به مقاله روزنامه شما در مورد تعطیلی بیمارستان ماینتون، می‌خواهم مخالفت قوی خود را با این پیشنهاد ابراز کنم، به دلایل زیر. اولاً، نزدیک‌ترین بیمارستان دیگه ۵۰ کیلومتر فاصله داره. ثانیاً، ۲۰۰ نفر در بیمارستان کار می‌کنن و اون‌ها شغلشون رو از دست می‌دن و کل منطقه متضرر می‌شه؛ یعنی بیمارستان سهم مهمی در اقتصاد محلی داره. در نهایت، تنها بیمارستان منطقه‌ایه که واحد سرطانی تخصصی داره. اما کنار گذاشتن مسائل اقتصادی و پزشکی، بیمارستان به وضوح به دلایل سیاسی بسته می‌شه، و این کاملاً غلطه. به طور خلاصه، تعطیلی بیمارستان ما برای مردم و اقتصاد این منطقه فاجعه‌ای خواهد بود. با احترام، آن گرین (خانم)"
