          answerFa: "| ۱ سس در اینجا معمولاً به سس‌های بطری شده مانند سس گوجه فرنگی اشاره دارد. سس به معنی سس مخصوصی است که با یک غذای خاص سرو می‌شود، مثلاً سس سفید، سس پنیر. | ۲ پلنت (Plant) به معنی تجهیزات سنگین، مثلاً ماشین‌آلات سنگین برای ساختمان است. پلنت می‌تواند به معنی گیاهی برای کشت باشد. پلنت همچنین می‌تواند به معنی کارخانه یا تأسیسات بزرگ باشد، مثلاً نیروگاه هسته‌ای – جایی که برق تولید می‌شود. | ۳ نور (ناوبر) معمولاً به معنای روشنایی برای دید بهتر است، مثلاً نور برق یا چراغ قوه. در درخواست قابل شمارش 'Can I have / can you give me a light, please؟'، معمولاً به معنولیتر یا کبرت برای روشن کردن سیگار یا تنباکوی دودکش است."
