      instructionFa: "هر کلمه را با یک کلمه از جعبه تطبیق دهید. — جاهای خالی را با کلمات صفحه سمت چپ پر کنید. — به نظر شما چه انواع هوایی باعث وقوع موارد زیر شده است؟ برای هر مورد جمله‌ای بنویسید که قبل از آن بیاید. — چه انواع هوایی برای انجام این کارها بد و خوب هستند؟ — این نمودار به هر کسی که می‌خواهد از غرب ایرلند دیدن کند نشان می‌دهد در زمان‌های مختلف سال چه هوایی انتظار داشته باشد. نموداری مشابه برای کشور یا منطقه خود بسازید.",
