          answerEn: "Suggested answers: | 1 ... the fair, bald guy. or straight-/curly-haired man. | 2 ... scruffy and untidy-looking/messy-looking. | 3 ... that slim, dark-haired woman over there. | 4 ... unattractive, in fact. (You could also say he/she was 'rather plain' or 'rather ordinary', if you felt they were neither attractive nor unattractive. 'Ugly' is a very strong word indeed, and could be offensive.) | 5 ... a teenager / in her twenties. (Another useful expression is 'she's a youngster', for a person who is a teenager or who is still very young.)",
          answerFa: "پاسخ‌های پیشنهادی: | ۱ ... آن مرد لاغر و موهای کم‌پشت. یا مرد موهای صاف/پیچ‌دار. | ۲ ... به نظر کثیف و به‌هم‌ریخته/شلخته. | ۳ ... آن زن لاغر و موهای تیره آنجا. | ۴ ... غیرجذاب، در واقع. (می‌توانید بگویید 'کمی معمولی' یا 'کمی ساده'، اگر فکر می‌کنید هم جذاب نیستند و هم غیرجذاب. 'زشت' یک کلمه بسیار قوی است و ممکن است توهین‌آمیز باشد.) | ۵ ... نوجوان / در اوایل بیست سالگی. (عبارت مفید دیگر 'او یک جوان است' است، برای شخصی که نوجوان است یا هنوز بسیار جوان است.)"
